using System.Linq;
using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.Logging;
using Moq;
using Xunit;

namespace ContosoUniversity.Tests.Controllers
{
    public class CoursesControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly CoursesController _controller;
        private readonly Mock<IWebHostEnvironment> _mockEnv;
        private readonly Mock<ILogger<CoursesController>> _mockLogger;

        public CoursesControllerTests()
        {
            _context = TestDbContextFactory.Create();
            _mockEnv = new Mock<IWebHostEnvironment>();
            _mockEnv.Setup(e => e.WebRootPath).Returns("/tmp/wwwroot");
            _mockEnv.Setup(e => e.ContentRootPath).Returns("/tmp");
            _mockLogger = new Mock<ILogger<CoursesController>>();
            _controller = new CoursesController(_context, _mockEnv.Object, _mockLogger.Object);
        }

        public void Dispose()
        {
            _controller.Dispose();
            _context.Dispose();
        }

        private Department SeedDepartment()
        {
            var dept = new Department
            {
                Name = "Engineering",
                Budget = 350000,
                StartDate = DateTime.Parse("2007-09-01")
            };
            _context.Departments.Add(dept);
            _context.SaveChanges();
            return dept;
        }

        private Course SeedCourse(int? deptId = null)
        {
            if (deptId == null)
            {
                deptId = SeedDepartment().DepartmentID;
            }
            var course = new Course
            {
                CourseID = 1050,
                Title = "Chemistry",
                Credits = 3,
                DepartmentID = deptId.Value
            };
            _context.Courses.Add(course);
            _context.SaveChanges();
            return course;
        }

        // ========== Index Tests ==========

        [Fact]
        public void Index_ReturnsViewWithCourses()
        {
            var dept = SeedDepartment();
            SeedCourse(dept.DepartmentID);

            var result = _controller.Index();

            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsAssignableFrom<List<Course>>(viewResult.Model);
            Assert.Single(model);
            Assert.Equal("Chemistry", model[0].Title);
        }

        [Fact]
        public void Index_EmptyDatabase_ReturnsEmptyList()
        {
            var result = _controller.Index();

            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsAssignableFrom<List<Course>>(viewResult.Model);
            Assert.Empty(model);
        }

        // ========== Details Tests ==========

        [Fact]
        public void Details_NullId_ReturnsBadRequest()
        {
            var result = _controller.Details(null);

            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Details_ValidId_ReturnsViewWithCourse()
        {
            var dept = SeedDepartment();
            var course = SeedCourse(dept.DepartmentID);

            var result = _controller.Details(course.CourseID);

            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsType<Course>(viewResult.Model);
            Assert.Equal("Chemistry", model.Title);
            Assert.Equal(3, model.Credits);
        }

        // ========== Create GET Tests ==========

        [Fact]
        public void Create_GET_ReturnsViewWithDepartmentSelectList()
        {
            SeedDepartment();

            var result = _controller.Create();

            var viewResult = Assert.IsType<ViewResult>(result);
            Assert.NotNull(_controller.ViewBag.DepartmentID);
            Assert.IsType<Course>(viewResult.Model);
        }

        // ========== Create POST Tests ==========

        [Fact]
        public void Create_POST_ValidCourse_AddsAndRedirects()
        {
            var dept = SeedDepartment();
            var course = new Course
            {
                CourseID = 2001,
                Title = "New Course",
                Credits = 4,
                DepartmentID = dept.DepartmentID
            };

            var result = _controller.Create(course, null);

            var redirectResult = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirectResult.ActionName);
            Assert.Equal(1, _context.Courses.Count());
        }

        [Fact]
        public void Create_POST_InvalidModelState_ReturnsView()
        {
            var dept = SeedDepartment();
            _controller.ModelState.AddModelError("Title", "Required");
            var course = new Course { DepartmentID = dept.DepartmentID };

            var result = _controller.Create(course, null);

            var viewResult = Assert.IsType<ViewResult>(result);
            Assert.NotNull(_controller.ViewBag.DepartmentID);
        }

        [Fact]
        public void Create_POST_WithImage_InvalidExtension_ReturnsError()
        {
            var dept = SeedDepartment();
            var course = new Course
            {
                CourseID = 2001,
                Title = "New Course",
                Credits = 4,
                DepartmentID = dept.DepartmentID
            };
            var mockFile = new Mock<IFormFile>();
            mockFile.Setup(f => f.Length).Returns(1024);
            mockFile.Setup(f => f.FileName).Returns("test.exe");

            var result = _controller.Create(course, mockFile.Object);

            var viewResult = Assert.IsType<ViewResult>(result);
            Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
        }

        [Fact]
        public void Create_POST_WithImage_TooLarge_ReturnsError()
        {
            var dept = SeedDepartment();
            var course = new Course
            {
                CourseID = 2001,
                Title = "New Course",
                Credits = 4,
                DepartmentID = dept.DepartmentID
            };
            var mockFile = new Mock<IFormFile>();
            mockFile.Setup(f => f.Length).Returns(6 * 1024 * 1024); // 6MB
            mockFile.Setup(f => f.FileName).Returns("test.jpg");

            var result = _controller.Create(course, mockFile.Object);

            var viewResult = Assert.IsType<ViewResult>(result);
            Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
        }

        // ========== Edit GET Tests ==========

        [Fact]
        public void Edit_GET_NullId_ReturnsBadRequest()
        {
            var result = _controller.Edit((int?)null);

            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Edit_GET_NotFound_ReturnsNotFound()
        {
            var result = _controller.Edit(9999);

            Assert.IsType<NotFoundResult>(result);
        }

        [Fact]
        public void Edit_GET_ValidId_ReturnsViewWithCourse()
        {
            var dept = SeedDepartment();
            var course = SeedCourse(dept.DepartmentID);

            var result = _controller.Edit(course.CourseID);

            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsType<Course>(viewResult.Model);
            Assert.Equal("Chemistry", model.Title);
            Assert.NotNull(_controller.ViewBag.DepartmentID);
        }

        // ========== Edit POST Tests ==========

        [Fact]
        public void Edit_POST_ValidCourse_UpdatesAndRedirects()
        {
            var dept = SeedDepartment();
            var course = SeedCourse(dept.DepartmentID);
            _context.Entry(course).State = Microsoft.EntityFrameworkCore.EntityState.Detached;

            var updatedCourse = new Course
            {
                CourseID = course.CourseID,
                Title = "Updated Chemistry",
                Credits = 4,
                DepartmentID = dept.DepartmentID
            };

            var result = _controller.Edit(updatedCourse, null);

            var redirectResult = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirectResult.ActionName);
        }

        [Fact]
        public void Edit_POST_InvalidModelState_ReturnsView()
        {
            var dept = SeedDepartment();
            _controller.ModelState.AddModelError("Title", "Required");

            var result = _controller.Edit(new Course { DepartmentID = dept.DepartmentID }, null);

            Assert.IsType<ViewResult>(result);
        }

        [Fact]
        public void Edit_POST_WithInvalidImageExtension_ReturnsError()
        {
            var dept = SeedDepartment();
            var course = SeedCourse(dept.DepartmentID);
            _context.Entry(course).State = Microsoft.EntityFrameworkCore.EntityState.Detached;

            var mockFile = new Mock<IFormFile>();
            mockFile.Setup(f => f.Length).Returns(1024);
            mockFile.Setup(f => f.FileName).Returns("test.pdf");

            var editedCourse = new Course
            {
                CourseID = course.CourseID,
                Title = "Chemistry",
                Credits = 3,
                DepartmentID = dept.DepartmentID
            };

            var result = _controller.Edit(editedCourse, mockFile.Object);

            var viewResult = Assert.IsType<ViewResult>(result);
            Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
        }

        // ========== Delete GET Tests ==========

        [Fact]
        public void Delete_GET_NullId_ReturnsBadRequest()
        {
            var result = _controller.Delete(null);

            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Delete_GET_ValidId_ReturnsViewWithCourse()
        {
            var dept = SeedDepartment();
            var course = SeedCourse(dept.DepartmentID);

            var result = _controller.Delete(course.CourseID);

            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsType<Course>(viewResult.Model);
            Assert.Equal("Chemistry", model.Title);
        }

        // ========== Delete POST Tests ==========

        [Fact]
        public void DeleteConfirmed_RemovesCourseAndRedirects()
        {
            var dept = SeedDepartment();
            var course = SeedCourse(dept.DepartmentID);

            var result = _controller.DeleteConfirmed(course.CourseID);

            var redirectResult = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirectResult.ActionName);
            Assert.Empty(_context.Courses);
        }
    }
}

