using System;
using System.Collections.Generic;
using System.Linq;
using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Models.SchoolViewModels;
using Microsoft.AspNetCore.Mvc;
using Xunit;

namespace ContosoUniversity.Tests.Controllers
{
    public class InstructorsControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly InstructorsController _controller;

        public InstructorsControllerTests()
        {
            _context = TestDbContextFactory.Create();
            _controller = new InstructorsController(_context);
        }

        public void Dispose()
        {
            _controller.Dispose();
            _context.Dispose();
        }

        private Instructor SeedInstructorWithCourses()
        {
            var dept = new Department
            {
                Name = "Engineering",
                Budget = 350000,
                StartDate = DateTime.Parse("2007-09-01")
            };
            _context.Departments.Add(dept);
            _context.SaveChanges();

            var course = new Course
            {
                CourseID = 1050,
                Title = "Chemistry",
                Credits = 3,
                DepartmentID = dept.DepartmentID,
                Enrollments = new List<Enrollment>()
            };
            _context.Courses.Add(course);
            _context.SaveChanges();

            var instructor = new Instructor
            {
                FirstMidName = "Kim",
                LastName = "Abercrombie",
                HireDate = DateTime.Parse("1995-03-11"),
                OfficeAssignment = new OfficeAssignment { Location = "Smith 17" },
                CourseAssignments = new List<CourseAssignment>
                {
                    new CourseAssignment { CourseID = course.CourseID }
                }
            };
            _context.Instructors.Add(instructor);
            _context.SaveChanges();

            return instructor;
        }

        private Instructor SeedSimpleInstructor()
        {
            var instructor = new Instructor
            {
                FirstMidName = "Roger",
                LastName = "Harui",
                HireDate = DateTime.Parse("1998-07-01"),
                CourseAssignments = new List<CourseAssignment>()
            };
            _context.Instructors.Add(instructor);
            _context.SaveChanges();
            return instructor;
        }

        // ========== Index Tests ==========

        [Fact]
        public void Index_NoSelection_ReturnsViewWithInstructors()
        {
            SeedSimpleInstructor();

            var result = _controller.Index(null, null);

            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsType<InstructorIndexData>(viewResult.Model);
            Assert.Single(model.Instructors);
        }

        [Fact]
        public void Index_WithInstructorId_PopulatesCourses()
        {
            var instructor = SeedInstructorWithCourses();

            var result = _controller.Index(instructor.ID, null);

            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsType<InstructorIndexData>(viewResult.Model);
            Assert.NotNull(model.Courses);
            Assert.Single(model.Courses);
            Assert.Equal("Chemistry", model.Courses.First().Title);
        }

        [Fact]
        public void Index_EmptyDatabase_ReturnsEmptyInstructors()
        {
            var result = _controller.Index(null, null);

            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsType<InstructorIndexData>(viewResult.Model);
            Assert.Empty(model.Instructors);
        }

        // ========== Details Tests ==========

        [Fact]
        public void Details_NullId_ReturnsBadRequest()
        {
            var result = _controller.Details(null);

            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Details_NotFound_ReturnsNotFound()
        {
            var result = _controller.Details(999);

            Assert.IsType<NotFoundResult>(result);
        }

        [Fact]
        public void Details_ValidId_ReturnsViewWithInstructor()
        {
            var instructor = SeedSimpleInstructor();

            var result = _controller.Details(instructor.ID);

            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsType<Instructor>(viewResult.Model);
            Assert.Equal("Harui", model.LastName);
            Assert.Equal("Roger", model.FirstMidName);
        }

        // ========== Create GET Tests ==========

        [Fact]
        public void Create_GET_ReturnsViewWithAssignedCourseData()
        {
            // Add a course so PopulateAssignedCourseData has something to work with
            var dept = new Department
            {
                Name = "Test",
                Budget = 100000,
                StartDate = DateTime.Parse("2007-09-01")
            };
            _context.Departments.Add(dept);
            _context.SaveChanges();
            _context.Courses.Add(new Course
            {
                CourseID = 100,
                Title = "TestCourse",
                Credits = 3,
                DepartmentID = dept.DepartmentID
            });
            _context.SaveChanges();

            var result = _controller.Create();

            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsType<Instructor>(viewResult.Model);
            Assert.NotNull(model.CourseAssignments);
            Assert.NotNull(_controller.ViewBag.Courses);
        }

        // ========== Create POST Tests ==========

        [Fact]
        public void Create_POST_ValidInstructor_AddsAndRedirects()
        {
            var instructor = new Instructor
            {
                FirstMidName = "New",
                LastName = "Instructor",
                HireDate = DateTime.Parse("2020-01-01"),
                CourseAssignments = new List<CourseAssignment>()
            };

            var result = _controller.Create(instructor, null);

            var redirectResult = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirectResult.ActionName);
            Assert.Single(_context.Instructors);
        }

        [Fact]
        public void Create_POST_WithSelectedCourses_AddsAssignments()
        {
            var dept = new Department
            {
                Name = "Test",
                Budget = 100000,
                StartDate = DateTime.Parse("2007-09-01")
            };
            _context.Departments.Add(dept);
            _context.SaveChanges();

            var course = new Course
            {
                CourseID = 100,
                Title = "TestCourse",
                Credits = 3,
                DepartmentID = dept.DepartmentID
            };
            _context.Courses.Add(course);
            _context.SaveChanges();

            var instructor = new Instructor
            {
                FirstMidName = "New",
                LastName = "Instructor",
                HireDate = DateTime.Parse("2020-01-01")
            };

            var result = _controller.Create(instructor, new[] { "100" });

            var redirectResult = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirectResult.ActionName);
            var saved = _context.Instructors.First();
            Assert.Single(_context.CourseAssignments.Where(ca => ca.InstructorID == saved.ID));
        }

        [Fact]
        public void Create_POST_InvalidModelState_ReturnsView()
        {
            // Seed a course for PopulateAssignedCourseData
            var dept = new Department { Name = "Test", Budget = 100000, StartDate = DateTime.Parse("2007-09-01") };
            _context.Departments.Add(dept);
            _context.SaveChanges();
            _context.Courses.Add(new Course { CourseID = 100, Title = "Test", Credits = 3, DepartmentID = dept.DepartmentID });
            _context.SaveChanges();

            _controller.ModelState.AddModelError("LastName", "Required");
            var instructor = new Instructor
            {
                FirstMidName = "New",
                HireDate = DateTime.Parse("2020-01-01"),
                CourseAssignments = new List<CourseAssignment>()
            };

            var result = _controller.Create(instructor, null);

            Assert.IsType<ViewResult>(result);
            Assert.NotNull(_controller.ViewBag.Courses);
        }

        // ========== Delete GET Tests ==========

        [Fact]
        public void Delete_GET_NullId_ReturnsBadRequest()
        {
            var result = _controller.Delete(null);

            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Delete_GET_NotFound_ReturnsNotFound()
        {
            var result = _controller.Delete(999);

            Assert.IsType<NotFoundResult>(result);
        }

        [Fact]
        public void Delete_GET_ValidId_ReturnsView()
        {
            var instructor = SeedSimpleInstructor();

            var result = _controller.Delete(instructor.ID);

            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsType<Instructor>(viewResult.Model);
            Assert.Equal("Harui", model.LastName);
        }

        // ========== Delete POST Tests ==========

        [Fact]
        public void DeleteConfirmed_RemovesInstructorAndRedirects()
        {
            var instructor = SeedInstructorWithCourses();

            var result = _controller.DeleteConfirmed(instructor.ID);

            var redirectResult = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirectResult.ActionName);
            Assert.Empty(_context.Instructors);
        }

        [Fact]
        public void DeleteConfirmed_NullsDepartmentAdministrator()
        {
            var instructor = SeedSimpleInstructor();
            var dept = new Department
            {
                Name = "TestDept",
                Budget = 100000,
                StartDate = DateTime.Parse("2007-09-01"),
                InstructorID = instructor.ID
            };
            _context.Departments.Add(dept);
            _context.SaveChanges();

            // Need office assignment for the delete query
            _context.OfficeAssignments.Add(new OfficeAssignment
            {
                InstructorID = instructor.ID,
                Location = "Office 1"
            });
            _context.SaveChanges();

            _controller.DeleteConfirmed(instructor.ID);

            var updatedDept = _context.Departments.First();
            Assert.Null(updatedDept.InstructorID);
        }
    }
}

using System;
using System.Collections.Generic;
using System.Dynamic;
using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Services;
using Microsoft.AspNetCore.Mvc;
using Xunit;

namespace ContosoUniversity.Tests.Controllers
{
    public class NotificationsControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly NotificationsController _controller;

        public NotificationsControllerTests()
        {
            _context = TestDbContextFactory.Create();
            _controller = new NotificationsController(_context);
            // Drain queue
            var service = new NotificationService();
            while (service.ReceiveNotification() != null) { }
            service.Dispose();
        }

        public void Dispose()
        {
            _controller.Dispose();
            _context.Dispose();
        }

        [Fact]
        public void Index_ReturnsViewResult()
        {
            var result = _controller.Index();

            Assert.IsType<ViewResult>(result);
        }

        [Fact]
        public void GetNotifications_EmptyQueue_ReturnsSuccessWithEmptyList()
        {
            var result = _controller.GetNotifications();

            Assert.IsType<JsonResult>(result);
            var value = result.Value;
            Assert.NotNull(value);
            // Use reflection to check the anonymous type
            var successProp = value.GetType().GetProperty("success");
            Assert.NotNull(successProp);
            Assert.True((bool)successProp.GetValue(value));

            var countProp = value.GetType().GetProperty("count");
            Assert.NotNull(countProp);
            Assert.Equal(0, (int)countProp.GetValue(value));
        }

        [Fact]
        public void GetNotifications_WithNotifications_ReturnsThemInOrder()
        {
            // Enqueue some notifications via the notification service on the controller
            var service = new NotificationService();
            service.SendNotification("Student", "1", "Alice", EntityOperation.CREATE);
            service.SendNotification("Course", "2", "Math", EntityOperation.UPDATE);
            service.Dispose();

            var result = _controller.GetNotifications();

            var value = result.Value;
            var successProp = value.GetType().GetProperty("success");
            Assert.True((bool)successProp.GetValue(value));

            var countProp = value.GetType().GetProperty("count");
            Assert.True((int)countProp.GetValue(value) >= 1);
        }

        [Fact]
        public void MarkAsRead_ReturnsSuccess()
        {
            var result = _controller.MarkAsRead(1);

            Assert.IsType<JsonResult>(result);
            var value = result.Value;
            var successProp = value.GetType().GetProperty("success");
            Assert.NotNull(successProp);
            Assert.True((bool)successProp.GetValue(value));
        }
    }
}

