        [Fact]
        public void Constructor_AddsItemsToList()
        {
            var items = new List<string> { "x", "y", "z" };

            var list = new PaginatedList<string>(items, 3, 1, 3);

            Assert.Contains("x", list);
            Assert.Contains("y", list);
            Assert.Contains("z", list);
        }

        [Fact]
        public void HasPreviousPage_PageIndex1_ReturnsFalse_KillsBoundaryMutation()
        {
            // If mutation changes > to >=, page 1 would incorrectly show HasPreviousPage=true
            var list = new PaginatedList<int>(new List<int>(), 30, 1, 10);

            Assert.Equal(1, list.PageIndex);
            Assert.False(list.HasPreviousPage);
        }

        [Fact]
        public void HasNextPage_OnLastPage_ReturnsFalse_KillsBoundaryMutation()
        {
            // 20 items, pageSize 10 => 2 pages. Page 2 is last.
            // If mutation changes < to <=, page 2 would incorrectly show HasNextPage=true
            var list = new PaginatedList<int>(new List<int> { 1, 2 }, 20, 2, 10);

            Assert.Equal(2, list.PageIndex);
            Assert.Equal(2, list.TotalPages);
            Assert.False(list.HasNextPage);
        }

        [Fact]
        public void HasNextPage_OnSecondToLastPage_ReturnsTrue()
        {
            // Ensures page before last correctly returns true
            var list = new PaginatedList<int>(new List<int>(), 30, 2, 10);

            Assert.Equal(3, list.TotalPages);
            Assert.True(list.HasNextPage);
        }

        [Fact]
        public void Create_CalculatesCorrectSkipAndTake()
        {
            var source = Enumerable.Range(1, 50).AsQueryable();

            var page3 = PaginatedList<int>.Create(source, 3, 10);

            Assert.Equal(10, page3.Count);
            Assert.Equal(21, page3[0]); // Skip(20).Take(10)
            Assert.Equal(30, page3[9]);
            Assert.Equal(5, page3.TotalPages);
            Assert.True(page3.HasPreviousPage);
            Assert.True(page3.HasNextPage);
        }
    }
}

