        [Fact]
        public void SendNotification_TwoArgOverload_DelegatesToFiveArgOverload()
        {
            _service.SendNotification("Instructor", "7", EntityOperation.UPDATE);

            var notification = _service.ReceiveNotification();

            Assert.NotNull(notification);
            Assert.Equal("Instructor (ID: 7) has been updated", notification.Message);
            Assert.Equal("UPDATE", notification.Operation);
        }

        [Fact]
        public void SendNotification_NullEntityType_DoesNotThrow()
        {
            // Exception should be swallowed by try-catch
            var ex = Record.Exception(() => _service.SendNotification(null, null, null, EntityOperation.CREATE));
            Assert.Null(ex);
        }

        [Fact]
        public void SendNotification_QueueEnforcesMaxLength()
        {
            // Send more than 500 notifications to test cap enforcement
            for (int i = 0; i < 510; i++)
            {
                _service.SendNotification("Entity", i.ToString(), "Name" + i, EntityOperation.CREATE);
            }

            int count = 0;
            while (_service.ReceiveNotification() != null) count++;
            Assert.True(count <= 500, $"Queue should be capped at 500 but had {count} items");
            Assert.True(count > 0, "Queue should contain some notifications");
        }
    }
}

